#include "flash.h"
#include "anim_script_api.h"

/*
 * Short animation scene (park background gfx_bg_park, pet pose 0) with parameter a.
 */
int anim_unused_park_text(int p0)
{
    anim_scene_window2(0xa);
    anim_draw_pic(0, gfx_bg_park, 0, 0x40, 0x24);
    anim_draw_pet(1, 0, 0, 0x56, 0x33);
    anim_draw_other_chara(4, 5, 0x10, 0x30, 0x32);
    anim_draw_pic(7, D_2089534, 0, 0x40, 0x12);
    p0 = anim_draw_text(8, (u8 *)p0, 1, 0xe, 9);
    anim_queue_sound(0xd);
    anim_frame(0x12c, 3);
    return p0;
}

